print.draft.v1"}, "copy": {"picker_label": "Get referred", "goal_strip_label": "Career Sprint", "progress_title": "{count} of {target} referrals", "stage_descriptions": {"warm_up": "Reconnect first. No ask.", "ask": "Ask for a referral", "follow_up": "A gentle nudge", "thank": "Say thanks"}}}'::jsonb),
